      // Create a commit linked to the task
      writeFileSync(join(tempDir, 'hier.ts'), 'export const h = 1;\n');
      git('add hier.ts', tempDir);
      git('commit -m "feat: hierarchy feature" -m "Task: @task-hier"', tempDir);

