273→ * This function replaces any invalid characters in the prefix
274→ * and pads to create a valid 26-character ULID.
275→ *
276→ * @param prefix - Optional prefix (invalid chars will be replaced)
277→ * @returns A valid 26-character ULID
278→ *
279→ * @example
280→ * // Generate deterministic ULID (use sequence for uniqueness)
281→ * const id = testUlid(); // '01000000000000000000000000'
282→ *
283→ * @example
284→ * // With prefix (great for debugging)
285→ * testUlid('TASK')    // '01TASK00000000000000000000'
286→ * testUlid('TASK', 1) // '01TASK00000001000000000001'
287→ * testUlid('TRAIT')   // '01TRAJT0000000000000000000' (I replaced with J)
288→ */
289→export function testUlid(prefix = '', sequence = 0): string {
290→  // Replace invalid Crockford chars: I->J, L->K, O->0, U->V
291→  const safePrefix = prefix.toUpperCase()
292→    .replace(/I/g, 'J')
293→    .replace(/L/g, 'K')
294→    .replace(/O/g, '0')
295→    .replace(/U/g, 'V');
296→
297→  // Start with timestamp-like prefix (01 = valid ULID start)
298→  const base = '01' + safePrefix;
299→
300→  // Pad with zeros, leaving room for sequence and checksum
301→  const padLength = 24 - base.length; // 26 - 2 for suffix
302→  const sequenceStr = sequence.toString().padStart(Math.min(padLength, 8), '0');
303→  const padded = base + sequenceStr.slice(0, padLength);
304→
305→  // Fill remaining with zeros and add a final valid char
306→  const filled = padded.padEnd(25, '0');
307→
308→  // Use a deterministic final char based on sequence for uniqueness
309→  const finalChar = CROCKFORD_BASE32[sequence % 32];
310→
311→  return (filled + finalChar).slice(0, 26);
312→}
313→
314→/**
315→ * Generate multiple unique test ULIDs with the same prefix
316→ *
317→ * @param prefix - Prefix for all ULIDs
318→ * @param count - Number of ULIDs to generate
319→ * @returns Array of unique valid ULIDs
320→ *
321→ * @example
322→ * const [id1, id2, id3] = testUlids('TASK', 3);
323→ */
324→export function testUlids(prefix: string, count: number): string[] {
325→  return Array.from({ length: count }, (_, i) => testUlid(prefix, i));
326→}
