     1→/**
     2→ * Shared CLI test utilities
     3→ *
     4→ * Provides centralized helpers for running kspec CLI commands in tests.
     5→ * Uses pre-built dist/cli/index.js for performance (eliminates tsx transpilation overhead).
     6→ *
     7→ * ## ULID Patterns for Test Fixtures
     8→ *
     9→ * ULIDs use Crockford base32 which EXCLUDES: I, L, O, U
    10→ * Valid characters: 0-9, A-H, J-K, M-N, P-T, V-Z
    11→ *
    12→ * Common test ULID mistakes:
    13→ * - ❌ 01TRAIT10... (contains I)
    14→ * - ❌ 01TASK100... (contains I)
    15→ * - ❌ 01MODULE0... (contains O and U)
    16→ * - ✅ 01TRATT100... (valid - no I, L, O, U)
    17→ * - ✅ 01TASK0000... (valid - T, A, S, K are allowed)
    18→ *
    19→ * Use testUlid() to generate valid test ULIDs with readable prefixes.
    20→ *
    21→ * ## YAML Fixture Creation
    22→ *
    23→ * Don't use JSON.stringify() for YAML - it produces invalid syntax.
    24→ * Options:
    25→ * 1. Use setupTempFixtures() with pre-built fixtures (preferred)
    26→ * 2. Write YAML strings directly with template literals
    27→ * 3. Use the yaml library: import { stringify } from 'yaml'
    28→ */
    29→import { execSync, spawnSync } from 'node:child_process';
    30→import * as fs from 'node:fs/promises';
    31→import * as path from 'node:path';
    32→import * as os from 'node:os';
    33→
    34→// Use built CLI for performance - requires `npm run build` before tests
    35→export const CLI_PATH = path.join(__dirname, '..', '..', 'dist', 'cli', 'index.js');
    36→
    37→// Fixtures directory for test data
    38→export const FIXTURES_DIR = path.join(__dirname, '..', 'fixtures');
    39→
    40→/**
    41→ * Options for running kspec CLI commands
    42→ */
    43→export interface KspecOptions {
    44→  /** Input to pipe to stdin */
    45→  stdin?: string;
    46→  /** Don't throw on non-zero exit code */
    47→  expectFail?: boolean;
    48→  /** Additional environment variables */
    49→  env?: Record<string, string>;
    50→}
    51→
    52→/**
    53→ * Result from running a kspec CLI command
    54→ */
    55→export interface KspecResult {
    56→  /** Exit code (0 = success) */
    57→  exitCode: number;
    58→  /** Standard output (trimmed) */
    59→  stdout: string;
    60→  /** Standard error (trimmed) */
    61→  stderr: string;
    62→}
    63→
    64→/**
    65→ * Run a kspec CLI command
    66→ *
    67→ * @param args - CLI arguments (e.g., "task list --json")
    68→ * @param cwd - Working directory to run the command in
    69→ * @param options - Optional settings for stdin, error handling, env vars
    70→ * @returns KspecResult with exitCode, stdout, stderr
    71→ * @throws Error if command fails and expectFail is not set
    72→ *
    73→ * @example
    74→ * // Simple command
    75→ * const result = kspec('task list', tempDir);
    76→ *
    77→ * @example
    78→ * // With stdin
    79→ * const result = kspec('item set @ref --status implemented', tempDir, { stdin: 'y' });
    80→ *
    81→ * @example
    82→ * // Expecting failure
    83→ * const result = kspec('task set @ref --priority 99', tempDir, { expectFail: true });
    84→ * expect(result.exitCode).toBe(1);
    85→ */
    86→export function kspec(args: string, cwd: string, options: KspecOptions = {}): KspecResult {
    87→  const { stdin, expectFail = false, env = {} } = options;
    88→
    89→  // Build clean env: strip ralph-specific vars that pollute tests when running
    90→  // inside a ralph loop. Tests that need these vars pass them explicitly via env.
    91→  const cleanEnv = { ...process.env };
    92→  const RALPH_ENV_VARS = ['KSPEC_RALPH_SESSION', 'KSPEC_SESSION_ID'];
    93→  for (const key of RALPH_ENV_VARS) {
    94→    if (!(key in env)) {
    95→      delete cleanEnv[key];
    96→    }
    97→  }
    98→
    99→  // Use spawnSync with shell to capture both stdout and stderr
   100→  // Always use shell mode to properly handle argument parsing and quoting
   101→  const result = spawnSync('/bin/sh', ['-c', `node ${CLI_PATH} ${args}`], {
   102→    cwd,
   103→    encoding: 'utf-8',
   104→    timeout: 30_000,
   105→    env: { ...cleanEnv, KSPEC_AUTHOR: '@test', ...env },
   106→    input: stdin !== undefined ? (stdin.endsWith('\n') ? stdin : stdin + '\n') : undefined,
   107→  });
   108→
   109→  // Detect timeout (spawnSync kills the process and sets signal)
   110→  if (result.signal === 'SIGTERM' && result.error?.message?.includes('ETIMEDOUT')) {
   111→    throw new Error(`Command timed out after 30s: node ${CLI_PATH} ${args}`);
   112→  }
   113→
   114→  const kspecResult: KspecResult = {
   115→    exitCode: result.status ?? 1,
   116→    stdout: (result.stdout || '').trim(),
   117→    stderr: (result.stderr || '').trim(),
   118→  };
   119→
   120→  // Handle errors
   121→  if (kspecResult.exitCode !== 0) {
   122→    if (expectFail) {
   123→      return kspecResult;
   124→    }
   125→
   126→    // For backwards compatibility: return stdout if present even on error
   127→    // (some commands exit non-zero with valid output)
   128→    if (kspecResult.stdout) {
   129→      return kspecResult;
   130→    }
   131→
   132→    throw new Error(`Command failed: node ${CLI_PATH} ${args}\n${kspecResult.stderr || result.error?.message}`);
   133→  }
   134→
   135→  return kspecResult;
   136→}
   137→
   138→/**
   139→ * Run kspec and return just stdout (convenience wrapper)
   140→ *
   141→ * @param args - CLI arguments
   142→ * @param cwd - Working directory
   143→ * @param options - Optional settings
   144→ * @returns stdout trimmed
   145→ */
   146→export function kspecOutput(args: string, cwd: string, options: KspecOptions = {}): string {
   147→  return kspec(args, cwd, options).stdout;
   148→}
   149→
   150→/**
   151→ * Run kspec and return parsed JSON output
   152→ *
   153→ * @param args - CLI arguments (--json flag is added automatically)
   154→ * @param cwd - Working directory
   155→ * @param options - Optional settings
   156→ * @returns Parsed JSON response
   157→ */
   158→export function kspecJson<T>(args: string, cwd: string, options: KspecOptions = {}): T {
   159→  const result = kspec(`${args} --json`, cwd, options);
   160→  return JSON.parse(result.stdout);
   161→}
   162→
   163→// Legacy aliases for backwards compatibility
   164→export const kspecExpectFail = (args: string, cwd: string): string => {
   165→  const result = kspec(args, cwd, { expectFail: true });
   166→  return result.stderr || result.stdout;
   167→};
   168→
   169→export const kspecWithStatus = (args: string, cwd: string): KspecResult => {
   170→  return kspec(args, cwd, { expectFail: true });
   171→};
   172→
   173→/**
   174→ * Copy fixtures to a temp directory for isolated testing
   175→ *
   176→ * Excludes the 'multi-dir' subdirectory (use setupMultiDirFixtures() for that).
   177→ *
   178→ * @returns Path to the temp directory
   179→ */
   180→export async function setupTempFixtures(): Promise<string> {
   181→  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'kspec-test-'));
   182→
   183→  // Copy all fixtures except multi-dir
   184→  const entries = await fs.readdir(FIXTURES_DIR, { withFileTypes: true });
   185→  for (const entry of entries) {
   186→    if (entry.name === 'multi-dir') continue; // Skip multi-dir fixtures
   187→    const source = path.join(FIXTURES_DIR, entry.name);
   188→    const dest = path.join(tempDir, entry.name);
   189→    if (entry.isDirectory()) {
   190→      await fs.cp(source, dest, { recursive: true });
   191→    } else {
   192→      await fs.copyFile(source, dest);
   193→    }
   194→  }
   195→
   196→  return tempDir;
   197→}
   198→
   199→/**
   200→ * Copy multi-directory daemon fixtures to a temp directory
   201→ *
   202→ * Creates isolated copies of multiple kspec projects for testing
   203→ * multi-directory daemon functionality.
   204→ *
   205→ * @returns Path to the temp directory containing project subdirectories
   206→ *
   207→ * @example
   208→ * const fixturesRoot = await setupMultiDirFixtures();
   209→ * const projectA = path.join(fixturesRoot, 'project-a');
   210→ * const projectB = path.join(fixturesRoot, 'project-b');
   211→ * const projectInvalid = path.join(fixturesRoot, 'project-invalid');
   212→ *
   213→ * // Clean up when done
   214→ * await cleanupTempDir(fixturesRoot);
   215→ */
   216→export async function setupMultiDirFixtures(): Promise<string> {
   217→  const multiDirSource = path.join(FIXTURES_DIR, 'multi-dir');
   218→  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'kspec-multi-'));
   219→  await fs.cp(multiDirSource, tempDir, { recursive: true });
   220→  return tempDir;
   221→}
   222→
   223→/**
   224→ * Clean up a temp directory
   225→ *
   226→ * @param dir - Directory to remove
   227→ */
   228→export async function cleanupTempDir(dir: string): Promise<void> {
   229→  await fs.rm(dir, { recursive: true, force: true });
   230→}
   231→
   232→/**
   233→ * Create an empty temp directory (no fixtures)
   234→ *
   235→ * @param prefix - Optional prefix for the temp directory name
   236→ * @returns Path to the temp directory
   237→ */
   238→export async function createTempDir(prefix = 'kspec-test-'): Promise<string> {
   239→  return fs.mkdtemp(path.join(os.tmpdir(), prefix));
   240→}
   241→
   242→/**
