   256→ * @param cmd - Git command (without 'git' prefix)
   257→ * @param cwd - Working directory
   258→ */
   259→export function git(cmd: string, cwd: string): void {
   260→  execSync(`git ${cmd}`, { cwd, stdio: 'pipe' });
